import os, sys, shutil, argparse
from datetime import datetime
from PIL import Image
from PIL.ExifTags import TAGS

def get_date(path):
    try:
        img = Image.open(path)
        exif = img._getexif() or {}
        for k, v in exif.items():
            if TAGS.get(k) == 'DateTimeOriginal':
                return datetime.strptime(v, '%Y:%m:%d %H:%M:%S')
    except Exception:
        pass
    return datetime.fromtimestamp(os.path.getmtime(path))

p = argparse.ArgumentParser()
p.add_argument('folder')
p.add_argument('--dry-run', action='store_true')
p.add_argument('--pattern', default='%Y-%m-%d_%H%M%S')
a = p.parse_args()

seen = {}
for name in sorted(os.listdir(a.folder)):
    if not name.lower().endswith(('.jpg', '.jpeg', '.png', '.heic')):
        continue
    src = os.path.join(a.folder, name)
    stamp = get_date(src).strftime(a.pattern)
    ext = os.path.splitext(name)[1].lower()
    n = seen.get(stamp, 0)
    seen[stamp] = n + 1
    new = stamp + (f'_{n}' if n else '') + ext
    dst = os.path.join(a.folder, new)
    if a.dry_run:
        print(name, '->', new)
    else:
        shutil.move(src, dst)
print('done', file=sys.stderr)
